using System.Diagnostics;
using System.Text;
using System.Text.RegularExpressions;
using UnscRelay.Core;
static class LocalSessionChecks
{
    public static async Task<int> Run(){if(!OperatingSystem.IsWindows())throw new Exception("Windows required");var root=Path.Combine(Path.GetTempPath(),"relay-local-check-"+Guid.NewGuid().ToString("N"),"folder with spaces è");Directory.CreateDirectory(root);int count=0;
    void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+name);count++;}
    void Reject(Action action,string name){try{action();}catch(ArgumentException){Check(true,name);return;}catch(IOException){Check(true,name);return;}throw new Exception("Accepted "+name);}
    ConnectionProfile Profile(string shell,string commands="")=>new(){Name="Local fixture",Protocol="local",LocalShell=shell,StartupDirectory=root,StartupCommands=commands};
    async Task Wait(Func<bool> done,string name){var until=DateTime.UtcNow.AddSeconds(15);while(!done()&&DateTime.UtcNow<until)await Task.Delay(30);Check(done(),name);}
    try{
        Profile("cmd").Validate();Check(true,"Local profile needs no host or SSH username");Reject(()=>Profile("bad").Validate(),"Unknown shell rejected");Reject(()=> (Profile("cmd") with{StartupCommands="bad\0text"}).Validate(),"NUL startup text rejected");Reject(()=> (Profile("cmd") with{KeyId="secret"}).Validate(),"SSH credentials rejected for local profile");Reject(()=>LocalLaunch.Create(Profile("cmd") with{StartupDirectory=Path.Combine(root,"missing")},root),"Missing initial directory rejected");
        var marker=Path.Combine(root,"must-not-run.txt");using(var plan=LocalLaunch.Create(Profile("cmd","echo anything > \""+marker+"\""),root)){Check(!File.Exists(marker),"Planning startup does not execute commands");Check(plan.CommandLine.Contains("startup.cmd"),"CMD multiline commands use isolated script");}
        Check(LocalShell.Quote("--distribution")=="--distribution", "WSL switches are not spuriously quoted");
        Check(!Directory.EnumerateFiles(root,"startup.cmd",SearchOption.AllDirectories).Any(),"Temporary startup script removed after plan disposal");
        foreach(var shell in new[]{"cmd","powershell","pwsh"}){
            if(LocalShell.Executable(shell)==null){Console.WriteLine("SKIP "+shell+" unavailable");continue;}
            var content=new StringBuilder();var sync=new object();string Text(){lock(sync)return content.ToString();}var startup=shell=="cmd"?"echo START-CMD\necho café\ncd":"Write-Output 'START-PS'; Write-Output 'café'; (Get-Location).Path";
            await using var session=new LocalTerminal();var decoder=Encoding.UTF8.GetDecoder();session.Output+=bytes=>{lock(sync){var chars=new char[Encoding.UTF8.GetMaxCharCount(bytes.Length)];int n=decoder.GetChars(bytes,chars,false);content.Append(chars,0,n);}};
            await session.Start(Profile(shell,startup),root,100,30);await Wait(()=>Text().Contains(shell=="cmd"?"START-CMD":"START-PS"),shell+" startup commands appear in PTY");await Wait(()=>Text().Contains("folder with spaces"),shell+" starts in chosen directory");await Wait(()=>Text().Contains("café"),shell+" Unicode output preserved");
            session.Write(shell=="cmd"?"echo INTERACTIVE-^READY\r":"Write-Output ('INTERACTIVE-'+'READY')\r");await Wait(()=>Text().Contains("INTERACTIVE-READY"),shell+" accepts interactive input");await session.Resize(120,40);if(shell!="cmd"){session.Write("Write-Output ('SIZE-'+$Host.UI.RawUI.WindowSize.Width+'x'+$Host.UI.RawUI.WindowSize.Height)\r");await Wait(()=>Text().Contains("SIZE-120x40"),shell+" observes PTY resize");}
            if(shell!="cmd"){session.Write("Start-Sleep -Seconds 30\r");await Task.Delay(300);session.Write("\x03");await Task.Delay(100);session.Write("Write-Output ('AFTER-'+'CANCEL')\r");await Wait(()=>Text().Contains("AFTER-CANCEL"),shell+" Ctrl+C interrupts foreground command");}
            session.Write("exit\r");await Wait(()=>!session.Running,shell+" exit leaves no running shell");await session.DisposeAsync();
        }
        // Only this child tree is owned; an unrelated process must survive closing a terminal.
        using var unrelated=Process.Start(new ProcessStartInfo(LocalShell.Executable("cmd")!){UseShellExecute=false,CreateNoWindow=true,ArgumentList={"/D","/C","ping -n 30 127.0.0.1 >nul"}})!;
        try{var treeProfile=Profile("powershell","$p=Start-Process -FilePath $env:ComSpec -ArgumentList '/D','/K','echo CHILD' -PassThru; $p.Id | Set-Content -LiteralPath '"+Path.Combine(root,"child.pid").Replace("'","''")+"'");await using var tree=new LocalTerminal();tree.Output+=_=>{};await tree.Start(treeProfile,root,80,25);await Wait(()=>File.Exists(Path.Combine(root,"child.pid")),"Child process fixture created");var child=int.Parse(File.ReadAllText(Path.Combine(root,"child.pid")).Trim());await tree.DisposeAsync();await Task.Delay(250);bool exists;try{using var p=Process.GetProcessById(child);exists=!p.HasExited;}catch(ArgumentException){exists=false;}Check(!exists,"Closing terminal ends owned child processes");Check(!unrelated.HasExited,"Closing terminal preserves unrelated processes");}finally{if(!unrelated.HasExited)unrelated.Kill(true);}
        var distros=await LocalShell.Distributions();Console.WriteLine("WSL distributions available: "+distros.Length);if(distros.Length>0){var text=new StringBuilder();await using var wsl=new LocalTerminal();wsl.Output+=b=>{var chunk=Encoding.UTF8.GetString(b);lock(text)text.Append(chunk);if(chunk.Contains("\x1b[6n"))try{wsl.Write("\x1b[1;1R");}catch(IOException){}};await wsl.Start(Profile("wsl","printf 'WSL-START\\n'; pwd") with{StartupDirectory="/tmp",WslDistribution=distros.FirstOrDefault(d=>!d.StartsWith("docker",StringComparison.OrdinalIgnoreCase))??distros[0]},root,100,30);await Wait(()=>{lock(text)return text.ToString().Contains("WSL-START");},"WSL startup command executes");await Wait(()=>{lock(text)return text.ToString().Contains("/tmp");},"WSL Linux initial directory applied");wsl.Write("printf 'WSL-%s\\n' INTERACTIVE\r");await Wait(()=>{lock(text)return text.ToString().Contains("WSL-INTERACTIVE");},"WSL interactive input works");wsl.Write("exit\r");await Wait(()=>!wsl.Running,"WSL client exits without terminating distribution");}else Console.WriteLine("SKIP real WSL: no installed distributions");
        Console.WriteLine(count+" local session checks passed");return 0;
    }finally{if(root.StartsWith(Path.GetTempPath(),StringComparison.OrdinalIgnoreCase)&&root.Contains("relay-local-check-"))Directory.Delete(Path.GetDirectoryName(root)!,true);}}
}
